<?php require_once "../config/database.php";require_once "../config/auth.php";require_role('driver');$uid=current_user()['id'];$rows=$conn->query("SELECT o.*,r.name restaurant_name,u.name customer_name FROM orders o JOIN restaurants r ON r.id=o.restaurant_id JOIN users u ON u.id=o.customer_id WHERE o.status IN ('ready','driver_received','picked_up','delivering') AND (o.driver_id IS NULL OR o.driver_id=$uid) ORDER BY o.id DESC");?><!doctype html><html lang="vi"><head><meta charset="utf-8"><title>Tài xế</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="container"><h1>🛵 Khu vực tài xế</h1><table class="table"><tr><th>Mã</th><th>Nhà hàng</th><th>Khách</th><th>Trạng thái</th><th></th></tr><?php while($o=$rows->fetch_assoc()):?><tr><td><?=$o['order_code']?></td><td><?=htmlspecialchars($o['restaurant_name'])?></td><td><?=htmlspecialchars($o['customer_name'])?></td><td><?=status_text($o['status'])?></td><td><a class="btn" href="orders.php?id=<?=$o['id']?>">Xử lý</a></td></tr><?php endwhile;?></table></main></body></html>